// Renders the listing artwork in marketing/images/ from the library's real API, a config file generated by the
// 3.0.0 jar (source/sample/), the self-test log of a 26.3 server boot, the mod logo and the bundled OFL fonts.
// Usage (from the repository root): NODE_PATH="$(npm root -g)" node marketing/source/render.cjs [name...]
// Requires the `playwright` package. Set CHROMIUM_PATH to use a Chromium other than the one Playwright expects.
const path = require('path');
const fs = require('fs');
const { pathToFileURL } = require('url');
const { chromium } = require('playwright');

