const sample = path.join(__dirname, 'sample');
const url = (file) => pathToFileURL(file).href;
const font = (file) => url(path.join(fonts, file));
const read = (file) => fs.readFileSync(path.join(sample, file), 'utf8').replace(/\r\n/g, '\n').trimEnd();

